'use strict';
async function manageUsers(){
 const [result,options,roles,policy]=await Promise.all([API.request('/users'),API.request('/users/options'),API.request('/security/roles'),API.request('/security/policy')]);
 const fixed=new Set(['admin','logistics_manager','site_supervisor','logistics_operator','production_dept']);
 dialog('系统管理 · 账号与角色',`<p>仅维护五个固定账号。旧身份停用保留历史关联。密码变更、停用和角色授权变更会撤销相应会话；角色授权不得突破规定的权限上限。</p><div class="user-list">${result.items.filter(u=>fixed.has(u.username)).map(u=>`<div class="user-row"><span><strong>${esc(u.display_name)}</strong> · ${esc(u.username)} · ${u.active?'启用':'停用'}</span><button class="button secondary" data-user-toggle="${u.id}" data-active="${!u.active}" ${u.id===CurrentUser.id?'disabled':''}>${u.active?'停用':'启用'}</button><button class="button secondary" data-user-reset="${u.id}">重置密码</button></div>`).join('')}</div><details><summary>已停用历史身份（${result.items.filter(u=>!fixed.has(u.username)).length}）</summary><p>${result.items.filter(u=>!fixed.has(u.username)).map(u=>esc(u.username)).join('、')}</p></details><h3>测试期入库自审</h3><p>仅TEST环境、仅production_dept入库审批；生产环境强制关闭。不会允许其他业务自审。</p><label><input id="production-self-review" type="checkbox" ${policy.production_receipt_self_review?'checked':''} ${AppConfig.environment!=='test'?'disabled':''}>启用生产管理部测试入库自审</label><button class="button secondary" id="save-auth-policy">保存配置</button><h3>角色权限</h3><label>角色<select id="role-policy">${roles.items.map(r=>`<option value="${esc(r.code)}">${esc(r.name)}</option>`).join('')}</select></label><form id="role-policy-form"><div id="role-checks"></div><button class="button primary">保存角色权限并撤销旧会话</button></form><p id="security-message" role="alert"></p>`);
 const showError=e=>$('security-message').textContent=e.message;
 for(const b of document.querySelectorAll('[data-user-toggle]'))b.onclick=async()=>{try{await API.request('/users/'+b.dataset.userToggle,{method:'PATCH',body:{active:b.dataset.active==='true'}});await manageUsers();}catch(e){showError(e);}};
 for(const b of document.querySelectorAll('[data-user-reset]'))b.onclick=()=>{const id=b.dataset.userReset;dialog('重置账号密码', '<form id="reset-password-form" class="user-form"><label>新密码（12—128字符）<input name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><p>请通过安全渠道交付给该账号使用者，保存后所有旧会话立即失效。</p><p id="reset-error" role="alert"></p><button class="button primary">保存新密码</button></form>');$('reset-password-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await API.request('/users/'+id+'/reset-password',{method:'POST',body:{password:e.target.elements.password.value}});e.target.reset();if(id===CurrentUser.id){location.reload();return;}await manageUsers();}catch(err){$('reset-error').textContent=err.message;e.submitter.disabled=false;}};};
 $('save-auth-policy').onclick=async()=>{try{await API.request('/security/policy',{method:'PATCH',body:{production_receipt_self_review:$('production-self-review').checked}});AppConfig.productionReceiptSelfReviewEnabled=$('production-self-review').checked;notify('配置已保存并记录审计。');}catch(e){showError(e);}};
 const draw=()=>{const r=roles.items.find(r=>r.code===$('role-policy').value);$('role-checks').innerHTML=r.caps.map(p=>`<label><input name="permission" type="checkbox" value="${esc(p)}" ${r.permissions.includes(p)?'checked':''} ${r.code==='admin'?'disabled':''}>${esc(p)}</label>`).join('');$('role-policy-form').querySelector('button').disabled=r.code==='admin';};$('role-policy').onchange=draw;draw();
 $('role-policy-form').onsubmit=async e=>{e.preventDefault();try{await API.request('/security/roles/'+$('role-policy').value,{method:'PUT',body:{permissions:[...document.querySelectorAll('#role-checks input:checked')].map(i=>i.value)}});await manageUsers();notify('权限已更新，相关会话已撤销。');}catch(err){showError(err);}};
}
